// paths so the API can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{BaseURL: baseURL})
}

// RegisterHandlersWithOptions registers handlers using the supplied options,
// including any per-operation middleware.
func RegisterHandlersWithOptions(router EchoRouter, si ServerInterface, options RegisterHandlersOptions) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.GET(options.BaseURL+"/tenants", wrapper.ListTenants, options.OperationMiddlewares["listTenants"]...)
	router.GET(options.BaseURL+"/record-types", wrapper.ListRecordTypes, options.OperationMiddlewares["listRecordTypes"]...)
	router.POST(options.BaseURL+"/record-types", wrapper.DefineRecordType, options.OperationMiddlewares["defineRecordType"]...)
	router.POST(options.BaseURL+"/record-types/validate", wrapper.ValidateRecordType, options.OperationMiddlewares["validateRecordType"]...)
	router.DELETE(options.BaseURL+"/record-types/:name", wrapper.DeleteRecordType, options.OperationMiddlewares["deleteRecordType"]...)
	router.GET(options.BaseURL+"/record-types/:name", wrapper.GetRecordType, options.OperationMiddlewares["getRecordType"]...)
	router.GET(options.BaseURL+"/record-types/:name/records", wrapper.ListRecords, options.OperationMiddlewares["listRecords"]...)
	router.POST(options.BaseURL+"/record-types/:name/records", wrapper.InsertRecord, options.OperationMiddlewares["insertRecord"]...)
	router.DELETE(options.BaseURL+"/record-types/:name/records/:id", wrapper.DeleteRecord, options.OperationMiddlewares["deleteRecord"]...)
	router.GET(options.BaseURL+"/record-types/:name/records/:id", wrapper.GetRecord, options.OperationMiddlewares["getRecord"]...)
	router.PUT(options.BaseURL+"/record-types/:name/records/:id", wrapper.UpdateRecord, options.OperationMiddlewares["updateRecord"]...)
	router.GET(options.BaseURL+"/record-types/:name/labels", wrapper.ListLabels, options.OperationMiddlewares["listLabels"]...)

}
